import {unpaidTimeSource,unpaidTimeRows} from './planning-unpaid-time-data.js';
export const unpaidTimeDefinitions={unpaidTimePlanning:{title:'Keep a fictional weekly time plan separate from its independently quoted cash cost',fields:[
 ['unpaidTimeWork','Work plus travel requested in the week (hours)',45,0,100,1],
 ['unpaidTimeBefore','Own domestic/care time in the before scenario (hours/week)',30,0,100,1],
 ['unpaidTimeAfter','Own domestic/care time in the after scenario (hours/week)',26,0,100,1],
 ['unpaidTimeInvoice','Independent total paid-help quote per week (CAD)',120,0,2000,10],
 ['unpaidTimeCash','Cash independently available per week after other commitments (CAD)',200,0,3000,25]
]}};
export function unpaidTimePlan(input){
 const fixed=71,before=168-fixed-input.unpaidTimeWork-input.unpaidTimeBefore,after=168-fixed-input.unpaidTimeWork-input.unpaidTimeAfter,availableCents=Math.round(input.unpaidTimeCash*100)*4,invoiceCents=Math.round(input.unpaidTimeInvoice*100)*4;
 return {fixed,before,after,timeChange:after-before,beforeAssigned:168-before,afterAssigned:168-after,overscheduled:Math.max(0,-after),available:availableCents/100,invoice:invoiceCents/100,cashRemainder:(availableCents-invoiceCents)/100};
}
export function unpaidTimeResult(kind,input){
 if(kind!=='unpaidTimePlanning')throw Error('Unknown time-use topic.');
 const p=unpaidTimePlan(input),source=unpaidTimeSource,rows=unpaidTimeRows.slice(0,4);
 return {metrics:[['Signed unassigned hours in the after-scenario week',p.after,'decimal'],['Change in unassigned hours from the before scenario',p.timeChange,'decimal'],['Cash left after the quoted help over four weeks',p.cashRemainder,'money']],note:'Two fixed official source charts describe 2022 Time Use Survey daily person estimates, released 5 June 2024 and reviewed 25 October 2026. All-person daily means and activity-specific participant means have different denominators; daily participation is not past-year caregiver participation. These observations do not populate the controls. The final three figures are independent invented time and cash plans. The time model assigns exclusive non-overlapping blocks within one person’s 168-hour week: a fixed 71 hours for sleep, personal and other commitments, work/travel, and own domestic/care time. The 71-hour block is a teaching assumption, not a sleep, health or care standard. Before/after own-time inputs are separately assumed; a quote does not determine their difference. Negative remaining hours mean an overscheduled request, not a physically feasible week. Unassigned time does not establish usable leisure or paid-work capacity. The cash model compares four repeated weekly budgets with four total service invoices, rounding cash inputs to cents. Four weeks is not an average calendar month; receipt/invoice dates are not modeled. No provider-hour conversion, unpaid-work wage, additional earnings, benefits, taxes, borrowing or care-suitability conclusion is inferred.',charts:[
  {id:'unpaid-time-daily-means',type:'groupbar',title:'Compare the all-person mean with the activity-specific participant mean',unit:'decimal',tableUnit:'Hours per day',unitLabel:'2022 hours/day · persons aged 15+ · each activity has its own participant group',seriesNames:['All-person daily mean, including zero time','Daily mean among that activity’s participants'],rows:rows.map(r=>({label:r.label,values:[r.population.value,r.participants.value]})),source:source.url,sourceLabel:'Statistics Canada · Table 45-10-0104-01 · 2022 · hours/day',evidence:'Official statistics',note:'Canada, total persons aged 15+, all persons gender category; ten provinces, with source coverage exclusions. Participants performed the named activity on their reference day. The paired bars are conditional versus unconditional means, not two activities to add. Participants differ across rows, so summing participant means does not produce a person’s day. Values retain the published one-decimal hours; the article table preserves their published 95% bounds.'},
  {id:'unpaid-time-daily-participation',type:'intervalbar',title:'A separate percentage describes participation on the reference day',unit:'percent',unitLabel:'2022 percent of persons aged 15+ doing each activity that day; published 95% intervals',rows:rows.map(r=>({label:r.label,value:r.participation.value/100,lower:r.participation.lower/100,upper:r.participation.upper/100})),source:source.url,sourceLabel:'Statistics Canada · Table 45-10-0104-01 · daily participation',evidence:'Official survey estimates · published 95% confidence intervals',note:'One person can participate in several activities on a day, so the four percentages are not exclusive parts of 100%. This denominator differs from providing care at some time in a year. The intervals describe estimation uncertainty, not a personal schedule or future care probability. The daily means, rates and bounds are rounded as published; their rounded values need not multiply back to an exact identity.'},
  {id:'unpaid-time-exclusive-week',type:'waterfall',title:'Assign exclusive blocks before calling the remaining hours available',unit:'decimal',tableUnit:'Hours per week',unitLabel:'Hours in one invented 168-hour week; negative total means overscheduled',rows:[{label:'Total time in one week',value:168},{label:'Fixed sleep, personal and other',value:-p.fixed},{label:'Requested work plus travel',value:-input.unpaidTimeWork},{label:'Own domestic/care time after',value:-input.unpaidTimeAfter}],totalLabel:'Signed unassigned time after',evidence:'Hypothetical scenario',note:'The default requests total 71 + 45 + 26 = 142 hours, leaving 26 unassigned. Every block is assumed exclusive in this teaching ledger; the source diary’s simultaneous activities are not added as another copy of clock time. A negative endpoint shows that the requested exclusive blocks exceed 168. The tool does not normalize them into a feasible schedule or decide which need can safely be reduced.'},
  {id:'unpaid-time-before-after-remainder',type:'signedbar',title:'A different time outcome comes from the entered time assumptions',unit:'decimal',tableUnit:'Hours per week',unitLabel:'Signed unassigned hours out of 168 in each requested scenario',rows:[{label:'Before: own domestic/care',value:p.before},{label:'After: own domestic/care',value:p.after}],evidence:'Hypothetical scenario',note:'Work/travel and the fixed 71-hour block stay the same. At the defaults, own time is entered as 30 hours before and 26 after, so unassigned time rises from 22 to 26 hours. The four-hour difference is assumed, not estimated from a provider’s price or service hours. An after value above the before value for own time can reduce the remainder. Neither a positive remainder nor a quoted service establishes that a particular care arrangement is adequate.'},
  {id:'unpaid-time-four-week-cash',type:'waterfall',title:'Use an actual cash quote for the separate four-week budget',unit:'money',unitLabel:'CAD over exactly four weeks; independent of the time arithmetic',rows:[{label:'Four weeks of available cash',value:p.available},{label:'Four weekly service invoices',value:-p.invoice}],totalLabel:'Cash remainder, or unfunded gap',evidence:'Hypothetical scenario',note:'At the defaults, four weeks of CAD 200 available cash total CAD 800; four CAD 120 invoices total CAD 480, leaving CAD 320. This available cash is entered after other budget commitments and is not inferred from work hours. A CAD 250 weekly quote would leave an unfunded CAD 200 with the same cash input, while all time results remain unchanged. The model neither values unpaid work at a wage nor converts saved hours into earnings. Timing within the four weeks could create an additional cash need.'}
 ]};
}
